import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { UserItemService } from 'src/app/services/user-item.service';
import { NewItem } from 'src/app/models/new-item.model';

@Component({
  selector: 'app-payment',
  templateUrl: './payment.component.html',
  styleUrls: ['./payment.component.css'],
})
export class PaymentComponent implements OnInit {
  item!: NewItem;

  constructor(
    private route: ActivatedRoute,
    private service: UserItemService
  ) {}

  ngOnInit(): void {
    const itemId = Number(this.route.snapshot.queryParamMap.get('itemId'));
    this.service.getItemById(itemId).subscribe((data) => (this.item = data));
  }

  makePayment() {
    alert(`Payment successful for ₹${this.item.price}`);
    // Optional: Call a backend API to mark order as paid
  }
}
<div class="payment-card">
  <h2>Payment for {{ item.name }}</h2>
  <p>Description: {{ item.description }}</p>
  <p><strong>Total:</strong> ₹{{ item.price }}</p>
  <button (click)="makePayment()">Make Payment</button>
</div>
